#include "analog_vector_io.h"
esp_err_t analog_vector_io_init(analog_vector_io_t*io){if(!io)return ESP_ERR_INVALID_ARG;for(uint8_t i=0;i<8;i++){io->dac_channel[i]=i;io->adc_channel[i]=(uint8_t)(7-i);}esp_err_t a=ads7128_init(&io->adc,ADS7128_DEFAULT_ADDRESS);esp_err_t d=dac7578_init(&io->dac,DAC7578_DEFAULT_ADDRESS);if(a!=ESP_OK&&a!=ESP_ERR_NOT_SUPPORTED)return a;if(d!=ESP_OK&&d!=ESP_ERR_NOT_SUPPORTED)return d;return a==ESP_ERR_NOT_SUPPORTED&&d==ESP_ERR_NOT_SUPPORTED?ESP_ERR_NOT_SUPPORTED:ESP_OK;}
esp_err_t analog_vector_io_read_channel(analog_vector_io_t*io,analog_hid_channel_t c,uint16_t*x){if(!io||!x||c>=ANALOG_HID_COUNT)return ESP_ERR_INVALID_ARG;return ads7128_read_channel(&io->adc,io->adc_channel[c],x);}
esp_err_t analog_vector_io_write_channel(analog_vector_io_t*io,analog_hid_channel_t c,uint16_t x){if(!io||c>=ANALOG_HID_COUNT)return ESP_ERR_INVALID_ARG;return dac7578_write_channel(&io->dac,io->dac_channel[c],x,true);}
